package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenDecimalContextScopeTest {
 private static final String SYSTEM="na-nied-primary-2024-v1";
 @Test public void ExplicitNaSevenPlacementsRetainTheSixExistingTopicsAndEarlierRules(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow();
  for(String id:PublicDecimalContextsTest.IDS){assertTrue(pack.inGrade(id,7));assertTrue(pack.inGrade(id,6));var selected=GlobalCurriculum.limits(SYSTEM,id,7);assertTrue(selected.decimalContextMethods());assertTrue(selected.decimalDirectAnswers());assertEquals(99,selected.decimalContextCountMaximum());assertEquals(99,selected.wholeMaximum(1));assertEquals(3,selected.decimalPlaces(1));assertFalse(GlobalCurriculum.limits(SYSTEM,id,6).decimalContextMethods());assertFalse(GlobalCurriculum.limits("england-primary-2021-v1",id,6).decimalContextMethods());assertEquals(id,Catalog.get(id).id);}
  assertFalse(GlobalCurriculum.limits(SYSTEM,"decimalDiv",7).decimalContextMethods());assertFalse(GlobalCurriculum.limits(SYSTEM,"decimalMul",7).decimalContextMethods());
 }
 @Test public void NormalNaSevenFreshSuppliesAreTypedWithOptionalStrategiesInBothMcSettings(){
  for(String id:PublicDecimalContextsTest.IDS){var limits=GlobalCurriculum.limits(SYSTEM,id,7);Generator plain=new Generator(new Random(369)),mc=new Generator(new Random(369));List<String> recent=new ArrayList<>();Set<String> units=new HashSet<>();Set<Integer> places=new HashSet<>();boolean nonterm=false,finite=false,twoDigitCount=false;
   for(int i=0;i<160;i++){Question q=plain.next(id,recent,false,limits),other=mc.next(id,recent,true,limits);assertEquals(q.signature(),other.signature());assertFalse(recent.contains(q.signature()));recent.add(q.signature());var g=PublicDecimalContexts.readGeneral(q);assertNotNull(g);assertTrue(limits.allows(q));assertTrue(q.stepSupport);assertTrue(other.stepSupport);assertEquals("number",other.kind);assertTrue(other.choices.isEmpty());assertEquals(-1,other.correctChoice);assertNotNull(q.studyGuide);assertFalse(HelpPlan.forQuestion(q).canTransfer());units.add(g.unit());places.add(new BigDecimal(g.firstRaw()).scale());assertTrue(new BigDecimal(g.firstRaw()).compareTo(BigDecimal.valueOf(100))<0);if(g.secondRaw()!=null){assertTrue(new BigDecimal(g.secondRaw()).compareTo(BigDecimal.valueOf(100))<0);places.add(new BigDecimal(g.secondRaw()).scale());}if(g.count()!=null){assertTrue(g.count().compareTo(BigInteger.ONE)>=0&&g.count().compareTo(BigInteger.valueOf(99))<=0);twoDigitCount|=g.count().compareTo(BigInteger.TEN)>=0;}
    finite|=g.finitePossible();nonterm|=!g.finitePossible();String answer=g.finitePossible()?new BigDecimal(g.value().n).divide(new BigDecimal(g.value().d)).toPlainString():g.value().toString();for(String method:List.of("mental","written")){q.calculationMethod=method;assertTrue(new Checker().check(q,List.of(),List.of(answer)).correct());}assertEquals(q.signature(),other.signature());assertEquals(g.finitePossible()?"decimalValue":"fraction",q.answerFormat);assertEquals(!g.finitePossible(),FractionInput.defaultFraction(q));
   }
   assertEquals(Set.of("m","L","kg"),units);assertEquals(Set.of(1,2,3),places);assertTrue(finite);if(DecimalMeasureGroups.DIV.equals(id)||DecimalTwoStepStories.SHARE.equals(id))assertTrue(nonterm);if(DecimalMeasureGroups.supports(id)||DecimalTwoStepStories.supports(id))assertTrue(twoDigitCount);
  }
 }
 @Test public void DeclaredLimitsUsePublicOriginalQuantitiesCountAndExactResult(){
  Question wide=PublicDecimalContextsTest.q(DecimalTwoStepStories.SHARE,"200.500","0.501",1000,"kg");wide.answers=new String[]{"0"};wide.expression="0";assertTrue(CurriculumLimits.NONE.allows(wide));assertFalse(GlobalCurriculum.limits(SYSTEM,wide.skillId,7).allows(wide));assertFalse(new CurriculumLimits("wholeMaximum=99").allows(wide));assertFalse(new CurriculumLimits("decimalPlaces=2").allows(wide));assertFalse(new CurriculumLimits("decimalContextCountMaximum=99").allows(wide));assertTrue(new CurriculumLimits("maxResult=1").allows(wide));assertFalse(new CurriculumLimits("answerDecimalPlaces=3").allows(wide));
  Question q=PublicDecimalContextsTest.q(DecimalMeasureStories.ADD,"1.200","0.03",1,"m");assertTrue(new CurriculumLimits("decimalPlaces=3;secondDecimalPlaces=2;maxResult=1.23").allows(q));assertFalse(new CurriculumLimits("maxResult=1.229").allows(q));assertFalse(new CurriculumLimits("maxGiven=1").allows(q));assertFalse(new CurriculumLimits("minGiven=0.04").allows(q));assertFalse(new CurriculumLimits("sameDecimalPlaces=true").allows(q));assertFalse(new CurriculumLimits("answerDomain=integer").allows(q));assertFalse(new CurriculumLimits("integerSecondOperand=true").allows(q));
  Question counted=PublicDecimalContextsTest.q(DecimalMeasureGroups.MUL,"1.2","0",1000,"L");assertTrue(new CurriculumLimits("wholeMaximum=99").allows(counted));assertFalse(new CurriculumLimits("wholeDigits=1").allows(counted));assertTrue(new CurriculumLimits("wholeDigits=1;secondDigits=4").allows(counted));assertFalse(new CurriculumLimits("maxSecondOperand=99").allows(counted));assertFalse(new CurriculumLimits("maxGiven=99").allows(counted));assertFalse(new CurriculumLimits("maxResult=1199.9").allows(counted));
  for(String unsupported:List.of("denominators=2","wholeDecimalQuotients=true","decimalDivisorQuotients=true","includeWholeDecimalProducts=true","maxRegroups=1","roundingUnits=10"))assertFalse(unsupported,new CurriculumLimits(unsupported).allows(q));for(String malformed:List.of("decimalContextMethods=unknown","decimalContextCountMaximum=0","decimalContextCountMaximum=100")){try{new CurriculumLimits(malformed);fail(malformed);}catch(IllegalArgumentException expected){}}
 }
 @Test public void UnselectedAndEarlierSuppliersKeepSeedSignaturesChoicesAndSavedPermissions(){
  for(String id:PublicDecimalContextsTest.IDS){Catalog.Skill skill=Catalog.get(id);for(String system:List.of(SYSTEM,"england-primary-2021-v1")){var limits=GlobalCurriculum.limits(system,id,6);Random prior=new Random(3691);Generator current=new Generator(new Random(3691));List<String> recent=new ArrayList<>();for(int i=0;i<20;i++){Question expected=DecimalMeasureStories.supports(id)?DecimalMeasureStories.create(skill,prior,limits):DecimalMeasureGroups.supports(id)?DecimalMeasureGroups.create(skill,prior,limits):DecimalTwoStepStories.create(skill,prior,limits);Question actual=current.next(id,recent,false,limits);assertEquals(expected.signature(),actual.signature());assertEquals(expected.answerFormat,actual.answerFormat);assertFalse(actual.stepSupport);PublicDecimalContextsTest.equalGuides(expected.studyGuide,PublicDecimalContexts.guide(actual));recent.add(actual.signature());}}
   Random prior=new Random(3692);Question expected=DecimalMeasureStories.supports(id)?DecimalMeasureStories.create(skill,prior,CurriculumLimits.NONE):DecimalMeasureGroups.supports(id)?DecimalMeasureGroups.create(skill,prior,CurriculumLimits.NONE):DecimalTwoStepStories.create(skill,prior,CurriculumLimits.NONE);Question actual=new Generator(new Random(3692)).create(skill);assertEquals(expected.signature(),actual.signature());assertFalse(actual.stepSupport);assertEquals(expected.answerFormat,actual.answerFormat);
   var oldLimits=GlobalCurriculum.limits(SYSTEM,id,6);for(int seed=0;seed<40;seed++){Random legacyRandom=new Random(seed);Question legacy=DecimalMeasureStories.supports(id)?DecimalMeasureStories.create(skill,legacyRandom,oldLimits):DecimalMeasureGroups.supports(id)?DecimalMeasureGroups.create(skill,legacyRandom,oldLimits):DecimalTwoStepStories.create(skill,legacyRandom,oldLimits);Choices.build(legacy,skill,legacyRandom);oldLimits.constrainChoices(legacy);Question actualMc=new Generator(new Random(seed)).next(id,List.of(),true,oldLimits);assertEquals(legacy.signature(),actualMc.signature());assertEquals(legacy.choices,actualMc.choices);assertEquals(legacy.correctChoice,actualMc.correctChoice);assertFalse(actualMc.stepSupport);if(!actualMc.choices.isEmpty())assertTrue(new Checker().check(actualMc,List.of(),List.of(actualMc.choices.get(actualMc.correctChoice))).correct());}
  }
 }
}
